  c.querySelector('#pname').oninput = e => { d.name = e.target.value || 'Fahrer'; }; bindBtns(c, { ok: () => { G.Career.save(true); G.Game.mode === 'pause' ? UI.pauseMenu() : UI.showMainMenu(); el.overlay.classList.toggle('hidden', G.Game.mode !== 'pause'); } });
